runtime.queueEdgeJoins:
queueEdgeJoins(chunk) {
		const step = CHUNK_SIZE * chunk.size / chunk.segs;
		for (const neighbor of this.chunks.values()) {
			if (neighbor === chunk) continue;
			if (!terrainEdgeJoin(chunk, neighbor)) continue;
			const otherStep = CHUNK_SIZE * neighbor.size / neighbor.segs;
			const owner = step > otherStep ? chunk : otherStep > step ? neighbor : null;
			if (owner) {
				this.seamKeys.add(owner.key);
				chunk.edgePending?.add(owner.key);
				neighbor.edgePending?.add(owner.key);
			}
		}
	}

runtime.publishEdgeJoins:
publishEdgeJoins(chunk) {
		const tile = this.edgeTile(chunk), step = CHUNK_SIZE * chunk.size / chunk.segs;
		const joins = [];
		for (const neighbor of this.chunks.values()) {
			if (neighbor === chunk || CHUNK_SIZE * neighbor.size / neighbor.segs >= step) continue;
			const join = terrainEdgeJoin(chunk, neighbor);
			if (join) joins.push({
				...join,
				neighbor: this.edgeTile(neighbor)
			});
		}
		const geometry = joinTerrainEdges(tile, chunk.seamBaseVertices, joins);
		chunk.terrainMesh.geometry = geometry;
		if (chunk.backMesh) chunk.backMesh.geometry = geometry;
		tile.geometry.dispose();
	}

runtime.drainBuildQueue:
drainBuildQueue() {
		const deadline = performance.now() + this.uploadBudgetMs;
		let uploads = 0;
		// Completion order varies between workers; uploads follow current proximity.
		// Sort farthest-first so pop() removes the nearest result without shifting
		// every remaining ready item on each upload.
		if (this.ready.length > 1 && !this.readySorted) {
			for (const result of this.ready) {
				const key = result.key ?? tileKey(result.job.cx, result.job.cz, result.job.size);
				result.key = key;
				result.dist = this.desiredTiles.get(key)?.dist ?? Infinity;
			}
			this.ready.sort((a, b) => (b.dist ?? Infinity) - (a.dist ?? Infinity));
			this.readySorted = true;
		}
		while (this.ready.length && uploads < this.maxUploadsPerFrame && (uploads === 0 || performance.now() < deadline)) {
			const result = this.ready.pop();
			this.install(result.job, result.data);
			uploads++;
		}
		// Edge publication shares the existing attachment deadline and upload cap.
		while (this.seamKeys.size && uploads < this.maxUploadsPerFrame && (uploads === 0 || performance.now() < deadline)) {
			const key = this.seamKeys.values().next().value;
			this.seamKeys.delete(key);
			const chunk = this.chunks.get(key);
			if (chunk) {
				this.publishEdgeJoins(chunk);
				uploads++;
			}
		}
		this.dispatchWorkers();
		if (this.workers.size > 0) return;
		// Unsupported/failed workers share the upload deadline but can suspend
		// a tile between small sampling batches instead of overrunning it with
		// an entire near grid. One indivisible phase can still exceed the budget.
		let advances = 0;
		while ((this.fallback || this.pending.length) && uploads < this.maxUploadsPerFrame && advances < MAX_FALLBACK_STEPS_PER_FRAME && (advances === 0 && uploads === 0 || performance.now() < deadline)) {
			if (this.fallback && (this.fallback.job.generation !== this.generation || this.fallback.job.seed !== getWorldSeed() || !this.desiredTiles.has(this.fallback.key))) {
				this.cancelFallback();
			}
			if (!this.fallback) {
				const pending = this.pending.pop();
				if (!pending) break;
				const key = tileKey(pending.cx, pending.cz, pending.size);
				this.pendingKeys.delete(key);
				const job = this.requestFor(pending);
				if (!job) continue;
				const quality = pending.dist > 8 ? "fallback" : "full";
				this.fallback = {
					job,
					key,
					steps: generateTerrainGeometrySteps(job.cx * CHUNK_SIZE, job.cz * CHUNK_SIZE, job.lod, job.size, job.skirtEdges, quality)
				};
				this.activeKeys.add(key);
			}
			const current = this.fallback;
			let result;
			try {
				result = current.steps.next();
			} catch (error) {
				// Preserve error reporting, but never keep a terminated iterator that
				// would return an undefined payload on the next frame.
				this.cancelFallback();
				throw error;
			}
			advances++;
			if (result.done) {
				this.fallback = null;
				this.install(current.job, result.value);
				uploads++;
			}
		}
	}
